import json,hashlib,shutil
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import investigate_tradeoff_paths as x
h=x.h;OUT=x.OUT;d=x.d;lim=x.lim
results=json.loads((OUT/'results.json').read_text());extra={}
fig,axes=plt.subplots(1,2,figsize=(11,4.5))
for ax,(name,data) in zip(axes,results.items()):
 a,b=np.array(data['source_endpoints']);alt=np.load(OUT/f'{name}_alternative_start.npz')['states'][0]
 coarse=x.trace(a,b,alt,20,40);np.savez_compressed(OUT/f'{name}_alternative_start_20steps.npz',**coarse)
 def dense_check(st):
  steps=len(st)-1;u=np.linspace(0,1,steps*100+1);idx=np.minimum((u*steps).astype(int),steps-1);f=u*steps-idx
  mid=st[idx]+f[:,None]*(st[idx+1]-st[idx]);lim.validate(mid[:,:3]/1000)
  er=np.linalg.norm(h.fk(mid,d)-h.fk(a[None]+(b-a)[None]*u[:,None],h.BASE),axis=1)
  return er,mid,u
 e,mid,u=dense_check(coarse['states']);np.savez_compressed(OUT/f'{name}_dense_check.npz',errors=e,states=mid,u=u)
 saved=np.load(OUT/f'{name}_reproduced.npz');orig=saved['states'][0]
 fine=np.load(OUT/f'{name}_alternative_start.npz');fe,fm,fu=dense_check(fine['states'])
 trust=np.load(OUT/f'{name}_trust_region.npz');te,_,_=dense_check(trust['states'])
 extra[name]=dict(alternative_start_same_20steps=x.stats(coarse),dense_20steps=dict(max_mm=float(max(e)),checks=len(e)),dense_200steps=dict(max_mm=float(max(fe)),checks=len(fe)),trust_dense_max_mm=float(max(te)),original_start_exposure_mm=orig[:3],alternative_start_exposure_mm=alt[:3],original_start_rotation_deg=orig[4:]*180/np.pi,alternative_start_rotation_deg=alt[4:]*180/np.pi,alternative_start_tip_difference_mm=float(np.linalg.norm(h.fk(orig[None],d)-h.fk(alt[None],d))))
 ax.plot(saved['u']*100,saved['errors'],label='Original start',color='#bb5533');ax.plot(u*100,e,label='Alternative start, same 20 steps',color='#228877');ax.axhline(.5,color='gray',ls='--',label='0.5 mm completion threshold');ax.set(title=name.replace('_',' '),xlabel='Path progress (%)',ylabel='Tip deviation (mm)');ax.legend(fontsize=8)
x.write('additional_checks.json',extra);fig.suptitle('The same tube geometry can follow both paths from a different starting configuration');fig.tight_layout();fig.savefig(OUT/'path_diagnosis.png',dpi=170)
lines=['# Investigation of the two large path deviations','','## Finding','Both reference paths can be followed within the existing ideal model and measured hardware limits. The large errors are associated with the numerical controller becoming trapped on an unfavourable configuration branch as deployment reaches a boundary. They are not evidence that the reference paths lie outside the candidate geometry’s reachable workspace.','', 'This is a post-hoc diagnostic, not independent validation of an upgraded controller. Neither tube parameters nor the live viewer were changed.','', '| Case | Original worst error | Independent pointwise maximum | Alternative start, same 20 steps: densely checked maximum |','|---|---:|---:|---:|']
for name,r in results.items():lines.append(f"| {name} | {r['experiments']['reproduced']['max_mm']:.6f} mm | {r['pointwise']['max_mm']:.6f} mm | {extra[name]['dense_20steps']['max_mm']:.6f} mm |")
lines+=['','## What happened','On bank 0, path 10, the outer exposure reaches 72.5 mm (the front actuator at its full-extension limit). The controller then makes very little progress despite the reference moving on. On bank 1, path 14, the outer exposure reaches zero; that is the exterior-only model boundary, not the front carriage’s physical retraction stop. Much of the controller state then remains nearly unchanged while error accumulates.','', 'The existing solver computes a damped update, clips deployment fractions to bounds and accepts only error-reducing steps. On these branches, extending the iteration budget does not solve the problem. Reducing reference step size alone also fails. This is consistent with branch selection and boundary handling, rather than simply insufficient iterations. It does not establish a unique mathematical cause for every stalled step.','', '## Diagnostic controls','- Reproduced both saved 81-check traces to within 1e-7 mm.','- Increased iterations from 40 to 200 with unchanged starts and waypoints: both still failed.','- Increased waypoints from 20 steps to 200: both still failed from their original starts.','- Independently solved all 81 reference positions: all residuals below 0.007 mm. This alone would not prove a continuous path.','- Followed each path backwards from a separately solved endpoint, then used the resulting configuration at the original start for forward tracking. Both follow successfully.','- Repeated the forward path with the original 20-step and 40-iteration controller budget, changing only the starting configuration. Checked each resulting segment at 100 subdivisions (2,001 positions). Fine 200-step trajectories were also checked at 20,001 positions. All sampled states satisfy the same coupled constraints.','- A different bounded trust-region solver from the original start fixed the second path, but did not fully resolve the first. Simply swapping the local solver is therefore not a complete strategy.','', '## What this means for the optimisation decision','The candidate’s observed 43/48 score remains the correct score for the original controller and initialization protocol. Do not rewrite it as an improved score using only these repaired cases. The two large failures are now explained as avoidable numerical path-following failures in this model: feasible low-error alternatives have been constructed. This makes the tube candidate more promising than a diagnosis of geometric unreachability would. It does not yet establish robust path following from arbitrary configurations.','', 'A different start configuration places the tubes differently even though the tip starts at the same position. Reaching that alternative posture from an already fixed physical posture was not tested. If the start posture is prescribed, a posture transition or another feasible branch must be planned, rather than instantly changing actuator positions.','', '## Recommended next implementation','Add multiple initial IK solutions, path look-ahead to choose a feasible continuous branch, and boundary-aware recovery. Stop or flag execution when predicted residual exceeds the task tolerance instead of continuing with accumulating error. Any recovery must preserve continuous actuator motion and validate intervening positions. Then compare the original and proposed tubes using the same improved controller on fresh, untouched paths. Keep point-to-point and path-following claims separate.','', 'This investigation proves feasibility only at the checked resolution in the ideal exterior model. It does not test physical loads, torsion, friction, rate/acceleration limits, anatomical collision or experimental accuracy.','', '## Reproduction','```sh','MPLCONFIGDIR=/tmp/ctr-mpl .venv/bin/python tools/investigate_tradeoff_paths.py','MPLCONFIGDIR=/tmp/ctr-mpl .venv/bin/python tools/report_tradeoff_paths.py','```','Raw traces, independent pointwise states, reference endpoints, boundary coordinates and dense checks are saved alongside this report.']
(OUT/'investigation_report.md').write_text('\n'.join(lines)+'\n')
for p in [h.ROOT/'tools/investigate_tradeoff_paths.py',h.ROOT/'tools/report_tradeoff_paths.py']:
 shutil.copy2(p,OUT/p.name)
x.write('source_hashes.json',{str(p.relative_to(h.ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in [h.ROOT/'tools/investigate_tradeoff_paths.py',h.ROOT/'tools/report_tradeoff_paths.py',h.ROOT/'tools/optimise_measured_ctr.py',h.ROOT/'measured_hardware_simulator/design_constraints.py']})
print(json.dumps(extra,indent=2,default=lambda a:a.tolist()))
